pk() { echo ${PKS[$1]}; }   # bash arrays are 0-based: pk N is Anvil account N (the first run of edges.sh had +1 here, see the report)
addr() { cast wallet address --private-key $(pk $1); }
# deploy_app2 SALT_HEX STAGING SENTRIES_LIST -> "app consensus block"
deploy_app2() { local salt=$1 sp=$2 sentries=$3
  local r; r=$(cast send --rpc-url $RPC --private-key $PK0 $FACTORY "newDaveApp(bytes32,uint256,address,address[],(address,uint8,uint8,uint64,address),bytes32)" $TPL_HASH $sp $Z "$sentries" "$WCFG" "$salt" --json)
  python3 -I -c 'import sys,json;r=json.load(sys.stdin);l=r["logs"][-1]["data"];print("0x"+l[26:66],"0x"+l[90:130],int(r["blockNumber"],16))' <<<"$r"; }
# start_node2 NAME APP ACCOUNT DATADIR_SUFFIX
start_node2() { local name=$1 app=$2 acct=$3; local dd=$S/run/dd/$name; rm -rf "$dd"; mkdir -p "$dd"; docker rm -f rp-$name >/dev/null 2>&1
  docker run -d --name rp-$name --add-host host.docker.internal:host-gateway -e CARTESI_SLING_AUTH_PRIVATE_KEY=$(pk $acct) -e RUST_LOG=info,cartesi_sling_node=debug \
    -v "$TPL":/tpl:ro -v "$dd":/data $IMG --template-path /tpl --data-dir /data --blockchain-id 31337 --polling-interval 1 --snapshot-gap-inputs 1 --app-address $app --blockchain-http-endpoint ${RPC_NODE:-$RPC_IN} pk >/dev/null; }
wait_sealed_n() { local cons=$1 n=$2 max=${3:-400}; for i in $(seq 1 $max); do local c=$(cast logs --from-block 25 --address $cons 'EpochSealed(uint256,uint256,uint256,bytes32,bytes32,address)' -r $RPC --json | python3 -I -c 'import sys,json;print(len(json.load(sys.stdin)))'); [ "$c" -ge "$n" ] && return 0; sleep 5; done; return 1; }
wait_marker() { local c=$1 m=$2 max=${3:-300}; for i in $(seq 1 $max); do docker logs $c 2>&1 | grep -q "^$m" && return 0; sleep 2; done; return 1; }
sealed_list() { cast logs --from-block 25 --address $1 'EpochSealed(uint256,uint256,uint256,bytes32,bytes32,address)' -r $RPC --json | python3 -I -c 'import sys,json;print([(int(l["topics"][1],16),int(l["blockNumber"],16),"0x"+l["data"][130:194][:10]) for l in json.load(sys.stdin)])'; }
# Phase 2: deployer is account 39 (account 0 belongs to the parent session's runs); FACTORY2 selects the factory
source $S/p2/mainnet-factory.env 2>/dev/null
PKD=0xb68ac4aa2137dd31fd0732436d8e59e959bb62b4db2e6107b15f594caf0f405f
deploy_app3() { local salt=$1 sp=${2:-50} sentries=${3:-[]} factory=${4:-$FACTORY}
  local r; r=$(cast send --rpc-url $RPC --private-key $PKD $factory "newDaveApp(bytes32,uint256,address,address[],(address,uint8,uint8,uint64,address),bytes32)" $TPL_HASH $sp $Z "$sentries" "$WCFG" "$salt" --json)
  python3 -I -c 'import sys,json;r=json.load(sys.stdin);l=r["logs"][-1]["data"];print("0x"+l[26:66],"0x"+l[90:130],int(r["blockNumber"],16))' <<<"$r"; }
# start_node3 NAME APP ACCOUNT : data dir on a named Docker volume (G5), optional RPC_NODE
start_node3() { local name=$1 app=$2 acct=$3; docker rm -f rp-$name >/dev/null 2>&1; docker volume rm -f vol-$name >/dev/null 2>&1
  docker run -d --name rp-$name --add-host host.docker.internal:host-gateway -e CARTESI_SLING_AUTH_PRIVATE_KEY=$(pk $acct) -e RUST_LOG=info,cartesi_sling_node=debug \
    -v "$TPL":/tpl:ro -v vol-$name:/data $IMG --template-path /tpl --data-dir /data --blockchain-id 31337 --polling-interval 1 --snapshot-gap-inputs 1 --app-address $app --blockchain-http-endpoint ${RPC_NODE:-$RPC_IN} pk >/dev/null; }
# proxy NAME PORT "ENV..." -> background fault proxy, log in $OUT/NAME-proxy.jsonl
proxy() { local name=$1 port=$2; shift 2; for pid in $(lsof -t -iTCP:$port -sTCP:LISTEN 2>/dev/null); do kill $pid; done; nohup env BIND=0.0.0.0 PROXY_PORT=$port UPSTREAM=$RPC LOGFILE=$OUT/$name-proxy.jsonl TAG=$name "$@" python3 -I $P/harness/qa/rpc_fault_proxy.py >> $OUT/$name-proxy.log 2>&1 & sleep 1; }
